#!/usr/bin/env python3
"""
Round 202o (culprits), 14 October 2026. Needs round 201o.

Bioluminescent as Earth at Night plus shore glow; tools layout; Moon and Mars rows.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 202o (14 October)\n\nNeeds round 201o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Bioluminescent (asked 14 October: still green; wanted exactly Earth at\n  Night plus the blue glow along shores and other waters): the Black Marble\n  picture is solid again (no clear dark squares), the sea cover is gone, and\n  the shore glow, lake edges and rivers are drawn over the lights. Everything\n  else is Earth at Night as it was. Hard refresh needed (no app.js?v= bump).\n- Layers box tools: "Pull up every layer\'s dropdown", two lines tall, on the\n  left; Shading where points crowd and Raise figures as heights stacked\n  beside it, level with each other.\n- Off-planet invasion > From Earth > The Moon and Mars: eight rows\n  (moon_objects, moon_list, moon_artemis, moon_names, mars_list, mars_m20,\n  mars_msl, mars_names), route "leave" with body/bodyLayer. Ticked, the map\n  leaves Earth through Eyes and opens that body (bodies.html) with the\n  ticked rows on (BODY_PICK, posted as culpritsLayers); a body with nothing\n  ticked shows all its layers. Back to the map unticks them all.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round202o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 201o" not in h.read_text(encoding="utf-8"):
        sys.exit("round202o: round 201o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round202o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/bodies.html", "map/test.mjs", check=False)
            sys.exit("round202o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round202o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
